import{_ as p,c as e,o as r,af as t}from"./chunks/framework.zX5h-Rkw.js";const c=JSON.parse('{"title":"5.1 南武联合党宣言","description":"","frontmatter":{"title":"5.1 南武联合党宣言"},"headers":[],"relativePath":"archives_n_arts/arts/nambu_red/5.1.md","filePath":"archives_n_arts/arts/nambu_red/5.1.md"}'),n={name:"archives_n_arts/arts/nambu_red/5.1.md"};function s(_,a,i,d,l,o){return r(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="五" tabindex="-1">五 <a class="header-anchor" href="#五" aria-label="Permalink to “五”">​</a></h1><h2 id="_1-南武联合党宣言" tabindex="-1">1. 南武联合党宣言 <a class="header-anchor" href="#_1-南武联合党宣言" aria-label="Permalink to “1. 南武联合党宣言”">​</a></h2><p>香淳</p><h3 id="中文版" tabindex="-1">中文版 <a class="header-anchor" href="#中文版" aria-label="Permalink to “中文版”">​</a></h3><p>乾坤荡荡，南武之疆，溯其发端，实肇于革命同志之赤诚。山川形胜，已非旧观。呜呼！丹心贯日，赤帜凌霄，唯我劳农同志之心志耳！</p><p>乙丑岁（公历一九八四年），同志盟誓于南国地方，立革命之枢机，观时势之代谢，悯黔首之倒悬，则惕然而惧，怆然而思，振臂疾呼曰：革命惟民，不革则亡！无产者百载见掠，工农安得不困且殆者乎！</p><p>自帝制倾覆，圭江弄权，民共之治，荼毒寰宇。至于今时，剥削日炽。</p><p>考其缘由，学说乃革命之权舆，若不上承下教，终成虚设。何也？盖主义本属全民，岂能独私一二贤达？推原其故，非独南武若此也。</p><p>联合主义昭示：“无产先锋，患失阶级，曰不可不联，不联则殆，殆则必联，当速且急。”秉斯论也，吾党遂生！</p><p>当此存亡之秋，岂容逡巡？资本之毒，日渐浸淫；以我涣散之工农，抗民共之暴政，则处处受掣。既明无组织之祸也，革命者则曰：“兴联！兴联！”</p><p>然则理论未达闾阎，而于群众之觉迷，终无根本之变。何也？权贵据学则真假淆乱，公私混同，而未能普及群众，其弊岂独南武为然耶？</p><p>同志立斯党为： 理论一部，开民智也； 组织一部，建兵团也； 斗争一部，克压迫也； 宣传一部，播真理也。</p><p>将集兆民而训之，乃复惕然而惊，慨然而思，益加疾呼：“吾党固公而非私者也！凡我同志毋为贰心以贻阶级羞！”</p><p>《联合》之训曰：阶级既合，所向披靡。若弃联合之基而阔谈主义，挟异志而共谋，天下将讥革命之不成矣！</p><p>尝闻革命要义云：“自干部至于群众，未有不戮力同心而能成者。”故宣言：“同志同心，平等如一。”</p><p>今者同志亟待臂助，若有闻檄而应者乎，则何虑赤旗之不满寰宇哉！</p><h3 id="日文版" tabindex="-1">日文版 <a class="header-anchor" href="#日文版" aria-label="Permalink to “日文版”">​</a></h3><p>乾坤蕩蕩たる南武の疆、その発端を溯れば、実に革命同志の赤誠に肇る。山川形勝、旧観に非ず。嗚呼！丹心日に貫き、赤幟霄を凌ぐ、唯我が労農同志の心志のみ！</p><p>乙丑の歳（西暦一九八四年）、同志南国地方に盟誓し、革命の枢機を立て、時勢の代謝を観、黔首の倒懸を憫みて、則ち惕然として懼れ、愴然として思い、臂を振り疾呼して曰く：革命は惟れ民に在り、革せざれば則ち亡ぶ！無産者百載掠かれ、農工安くんぞ困み且つ殆からざらんや！</p><p>帝制傾覆してより、圭江権を弄び、民共の治、寰宇を荼毒す。今時に至り、剥削日熾なり。</p><p>其の缘由を考ふるに、学説は乃ち革命の権輿、上承下教せざれば、終に虚設と成る。何ぞや？蓋し主義は本と全民に属す、豈に独り一二の賢達に私せんや？其の故を推原するに、独り南武此れ若きに非ざるなり。</p><p>聯合主義示して曰く：「無産先鋒、階級を失うを患ふ、曰く聯せざるべからず、聯せざれば則ち殆し、殆うければ則ち必ず聯す、当に速か且つ急にすべし」。斯の論を秉りて、吾が党遂に生る！</p><p>此の存亡の秋に当り、豈に逡巡を容れんや？資本の毒、日に浸淫し；我が渙散の農工を以て、民共の暴政に抗すれば、則ち処々掣かる。既に組織無きの禍を明らむるや、革命者は則ち曰く：「聯を興せ！聯を興せ！」</p><p>然れども理論閭閻に達せず、而して群众の覚迷に於いて、終に根本の変無し。何ぞや？権貴学を據れば則ち真假淆乱し、公私混同し、而して群众に普及すること能わず、其の弊豈に独り南武然らんや？</p><p>同志斯の党を立てて： 理論一部は、民智を開く也； 組織一部は、兵団を建つる也； 斗争一部は、圧迫を克つ也； 宣伝一部は、真理を播く也。</p><p>兆民を集めて之を訓まんとし、乃ち復た惕然として驚き、慨然として思い、益々疾呼を加ふ：「吾が党固より公にして私に非ざる也！凡そ我が同志、貳心を為して以て階級を羞かしむる毋れ！」</p><p>《聯合》の訓に曰く：階級既に合すれば、向ふ所靡くなり。若し聯合の基を棄てて闊談主義し、異志を挟みて共に謀らば、天下将に革命の成らざるを譏らん！</p><p>嘗て革命要義を聞く云く：「幹部より群众に至るまで、力を戮め心を同うして能く成せる者未だ之有らざる也」。故に宣言す：「同志同心、平等一如たれ」。</p><p>今者同志亟に臂助を待つ、若し檄を聞きて応ずる者有らば、則ち何ぞ赤旗の寰宇に満たざるを慮らんや！</p>',29)])])}const m=p(n,[["render",s]]);export{c as __pageData,m as default};
